import { forwardRef } from 'react';
import { X, ChevronDown, Check } from 'lucide-react';

// Label
export const Label = forwardRef<HTMLLabelElement, React.LabelHTMLAttributes<HTMLLabelElement> & { required?: boolean }>(
  ({ className = '', required = false, children, ...props }, ref) => (
    <label
      ref={ref}
      className={`block text-sm font-medium text-gray-300 mb-1.5 ${className}`}
      {...props}
    >
      {children}
      {required && <span className="text-rose-400 ml-1" aria-hidden="true">*</span>}
    </label>
  )
);
Label.displayName = 'Label';

// Input
export const Input = forwardRef<HTMLInputElement, React.InputHTMLAttributes<HTMLInputElement> & { error?: string; label?: string; helperText?: string }>(
  ({ className = '', error, label, helperText, id, ...props }, ref) => {
    const inputId = id || label?.toLowerCase().replace(/\s+/g, '-');
    return (
      <div className="w-full">
        {label && <Label htmlFor={inputId}>{label}</Label>}
        <div className="relative">
          <input
            ref={ref}
            id={inputId}
            className={`w-full px-4 py-2.5 bg-white/5 border rounded-lg text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-violet-500/50 transition-colors ${error ? 'border-rose-500/50 focus:ring-rose-500/50' : 'border-white/10 hover:border-white/20'} ${className}`}
            aria-invalid={error ? 'true' : 'false'}
            aria-describedby={error ? `${inputId}-error` : helperText ? `${inputId}-helper` : undefined}
            {...props}
          />
          {error && <X className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-rose-400 pointer-events-none" />}
        </div>
        {error && <p id={`${inputId}-error`} className="mt-1.5 text-sm text-rose-400" role="alert">{error}</p>}
        {helperText && !error && <p id={`${inputId}-helper`} className="mt-1.5 text-sm text-gray-500">{helperText}</p>}
      </div>
    );
  }
);
Input.displayName = 'Input';

