// Select
export const Select = forwardRef<HTMLSelectElement, React.SelectHTMLAttributes<HTMLSelectElement> & { error?: string; label?: string; helperText?: string; options: { value: string; label: string }[] }>(
  ({ className = '', error, label, helperText, options, id, ...props }, ref) => {
    const selectId = id || label?.toLowerCase().replace(/\s+/g, '-');
    return (
      <div className="w-full">
        {label && <Label htmlFor={selectId}>{label}</Label>}
        <div className="relative">
          <select
            ref={ref}
            id={selectId}
            className={`w-full px-4 py-2.5 bg-white/5 border rounded-lg text-white focus:outline-none focus:ring-2 focus:ring-violet-500/50 transition-colors appearance-none pr-10 ${error ? 'border-rose-500/50 focus:ring-rose-500/50' : 'border-white/10 hover:border-white/20'} ${className}`}
            aria-invalid={error ? 'true' : 'false'}
            aria-describedby={error ? `${selectId}-error` : helperText ? `${selectId}-helper` : undefined}
            {...props}
          >
            {options.map(opt => (
              <option key={opt.value} value={opt.value}>{opt.label}</option>
            ))}
          </select>
          <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />
        </div>
        {error && <p id={`${selectId}-error`} className="mt-1.5 text-sm text-rose-400" role="alert">{error}</p>}
        {helperText && !error && <p id={`${selectId}-helper`} className="mt-1.5 text-sm text-gray-500">{helperText}</p>}
      </div>
    );
  }
);
Select.displayName = 'Select';

// Checkbox
export const Checkbox = forwardRef<HTMLInputElement, React.InputHTMLAttributes<HTMLInputElement> & { label: string; description?: string }>(
  ({ className = '', label, description, id, ...props }, ref) => {
    const checkboxId = id || label.toLowerCase().replace(/\s+/g, '-');
    return (
      <div className="flex items-start gap-3">
        <div className="relative mt-0.5">
          <input
            ref={ref}
            type="checkbox"
            id={checkboxId}
            className="w-4 h-4 rounded border-white/20 text-violet-500 focus:ring-2 focus:ring-violet-500/50 focus:ring-offset-2 focus:ring-offset-[#0a0e1a] bg-white/5 hover:border-violet-500/50 transition-colors"
            {...props}
          />
        </div>
        <div className="flex-1">
          <Label htmlFor={checkboxId} className="mb-0 cursor-pointer">{label}</Label>
          {description && <p className="text-sm text-gray-500 mt-0.5">{description}</p>}
        </div>
      </div>
    );
  }
);
Checkbox.displayName = 'Checkbox';

// Radio Group
export const RadioGroup = forwardRef<HTMLDivElement, { name: string; value?: string; onChange?: (value: string) => void; children: React.ReactNode; className?: string }>(
  ({ className = '', name, value, onChange, children, ...props }, ref) => (
    <div ref={ref} role="radiogroup" aria-label={name} className={className} {...props}>
      {children}
    </div>
  )
);
RadioGroup.displayName = 'RadioGroup';

export const Radio = forwardRef<HTMLInputElement, React.InputHTMLAttributes<HTMLInputElement> & { label: string }>(
  ({ className = '', label, ...props }, ref) => (
    <div className="flex items-center gap-2">
      <input
        ref={ref}
        type="radio"
        className="w-4 h-4 rounded-full border-white/20 text-violet-500 focus:ring-2 focus:ring-violet-500/50 focus:ring-offset-2 focus:ring-offset-[#0a0e1a] bg-white/5 hover:border-violet-500/50 transition-colors"
        {...props}
      />
      <Label className="mb-0 cursor-pointer">{label}</Label>
    </div>
  )
);
Radio.displayName = 'Radio';
